//! The entrypoint of the application

use std::path::PathBuf;

use bevy::ecs::system::RunSystemOnce;
use bevy::log::LogPlugin;
use bevy::prelude::*;
use clap::Parser;
use paiagram_core::settings::UserPreferences;
use paiagram_core::trip::class;
use paiagram_core::{entry, graph, i18n, import, problems, route, settings, station, trip};
use paiagram_rw::read::ReadPlugin;
use paiagram_rw::save::SavePlugin;
use serde::Deserialize;

struct PaiagramApp {
    bevy_app: App,
}

impl PaiagramApp {
    fn new(cc: &eframe::CreationContext) -> Self {
        // Modifications to the defualt style
        // TODO: define own styles
        cc.egui_ctx.global_style_mut(|style| {
            style.spacing.window_margin = egui::Margin::same(2);
            style.interaction.selectable_labels = false;
        });
        paiagram_ui::apply_custom_fonts(&cc.egui_ctx);
        if let Some(render_state) = cc.wgpu_render_state.as_ref() {
            cc.egui_ctx.data_mut(|data| {
                data.insert_temp(
                    egui::Id::new("wgpu_adapter_info"),
                    eframe::egui_wgpu::adapter_info_summary(&render_state.adapter.get_info()),
                );
                data.insert_temp(
                    egui::Id::new("wgpu_target_format"),
                    render_state.target_format,
                );
                let msaa_samples = if cfg!(target_arch = "wasm32") {
                    1_u32
                } else {
                    4_u32
                };
                data.insert_temp(egui::Id::new("wgpu_msaa_samples"), msaa_samples);
            });
        }
        let mut app = App::new();
        app.add_plugins(MinimalPlugins);
        app.add_plugins(LogPlugin::default());
        app.add_plugins((
            paiagram_ui::UiPlugin,
            entry::EntryPlugin,
            graph::GraphPlugin,
            route::RoutePlugin,
            import::ImportPlugin,
            trip::TripPlugin,
            station::StationPlugin,
            settings::SettingsPlugin,
            problems::ProblemsPlugin,
            class::ClassPlugin,
            ReadPlugin,
            SavePlugin,
            bevy::asset::AssetPlugin::default(), // TODO: remove
            bevy::scene::ScenePlugin,
        ));
        info!("Initialized Bevy App.");
        #[cfg(not(target_arch = "wasm32"))]
        let args = Arguments::parse();
        #[cfg(target_arch = "wasm32")]
        let args = parse_web_arguments();
        if let Err(e) = app.world_mut().run_system_once_with(handle_args, args) {
            error!("Failed to web arguments: {:?}", e);
        } else {
            info!("Arguments handled successfully.");
        }
        Self { bevy_app: app }
    }
}

#[cfg(target_arch = "wasm32")]
fn parse_web_arguments() -> Arguments {
    if let Some(search) =
        eframe::web_sys::window().and_then(|window| window.location().search().ok())
    {
        info!(?search, "Handling web args...");
        let query = search.strip_prefix('?').unwrap_or(&search);
        match serde_html_form::from_str::<Arguments>(&query) {
            Ok(args) => return args,
            Err(error) => error!("Failed to parse web args: {error}"),
        }
    }

    Arguments::default()
}

impl eframe::App for PaiagramApp {
    fn clear_color(&self, _visuals: &egui::Visuals) -> [f32; 4] {
        egui::Rgba::TRANSPARENT.to_array()
    }
    fn ui(&mut self, ui: &mut egui::Ui, frame: &mut eframe::Frame) {
        self.bevy_app.update();
        // TODO: remove this
        self.bevy_app
            .world_mut()
            .resource_mut::<UserPreferences>()
            .dark_mode = match ui.system_theme() {
            None => false,
            Some(egui::Theme::Dark) => true,
            Some(egui::Theme::Light) => false,
        };
        paiagram_ui::show_ui(ui, self.bevy_app.world_mut(), frame.info().cpu_usage);
    }
}

/// Arguments for the application.
#[derive(Parser, Default, Deserialize)]
#[command(version, about, long_about = None)]
struct Arguments {
    #[arg(
        short = 'o',
        long = "open",
        help = "Path to a .paiagram file (or any other compatible file formats) to open on startup",
        num_args = 1..
    )]
    #[serde(default)]
    open: Option<Vec<PathBuf>>,
    #[arg(long = "locale", help = "Set the localization")]
    #[serde(default)]
    locale: Option<String>,
}

fn handle_args(
    args: In<Arguments>,
    mut commands: Commands,
    mut languages: ResMut<UserPreferences>,
) {
    for path in args.open.iter().flatten() {
        #[cfg(target_arch = "wasm32")]
        {
            commands.trigger(import::DownloadFile {
                url: path.to_string_lossy().into_owned(),
            });
            continue;
        }

        #[cfg(not(target_arch = "wasm32"))]
        {
            let content = match std::fs::read(path) {
                Ok(c) => c,
                Err(e) => {
                    error!("Could not open {:?}: {:?}", path, e);
                    continue;
                }
            };
            if let Err(e) = import::load_and_trigger(path, content, &mut commands) {
                error!("Could not load {:?}: {:#?}", path, e);
                continue;
            }
        }
    }
    if let Some(locale) = args.locale.as_deref() {
        if languages.lang.set(locale) {
            info!("Successfully set language {}", locale);
        } else {
            error!("Unknown language identifier: {}", locale);
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
fn main() -> eframe::Result<()> {
    i18n::init();
    let native_options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_title("Drawer")
            .with_app_id("Paiagram")
            .with_inner_size([1280.0, 720.0]),
        renderer: eframe::Renderer::Wgpu,
        wgpu_options: eframe::egui_wgpu::WgpuConfiguration {
            desired_maximum_frame_latency: Some(2),
            ..default()
        },
        multisampling: 4,
        ..default()
    };
    eframe::run_native(
        "Paiagram Drawer",
        native_options,
        Box::new(|cc| Ok(Box::new(PaiagramApp::new(cc)))),
    )
}

#[cfg(target_arch = "wasm32")]
use wasm_bindgen::prelude::*;

#[cfg(target_arch = "wasm32")]
#[derive(Clone)]
#[wasm_bindgen]
pub struct WebHandle {
    runner: eframe::WebRunner,
}

#[cfg(target_arch = "wasm32")]
fn main() {
    i18n::init();
    use eframe::wasm_bindgen::JsCast as _;
    use eframe::web_sys;

    let web_options = eframe::WebOptions::default();

    wasm_bindgen_futures::spawn_local(async {
        let document = web_sys::window()
            .expect("No window")
            .document()
            .expect("No document");

        let canvas = if let Some(canvas) = document.get_element_by_id("paiagram_canvas") {
            canvas
                .dyn_into::<web_sys::HtmlCanvasElement>()
                .expect("paiagram_canvas was not a HtmlCanvasElement")
        } else {
            let canvas = document
                .create_element("canvas")
                .expect("Failed to create canvas element");
            canvas.set_id("paiagram_canvas");

            canvas
                .set_attribute("style", "display: block; width: 100%; height: 100%;")
                .ok();

            let body = document.body().expect("Failed to get document body");
            body.set_attribute(
                "style",
                "margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden;",
            )
            .ok();

            let html = document.document_element().expect("No document element");
            html.set_attribute(
                "style",
                "margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden;",
            )
            .ok();

            body.append_child(&canvas).expect("Failed to append canvas");
            canvas
                .dyn_into::<web_sys::HtmlCanvasElement>()
                .expect("Failed to cast canvas")
        };

        let start_result = eframe::WebRunner::new()
            .start(
                canvas,
                web_options,
                Box::new(|cc| Ok(Box::new(PaiagramApp::new(cc)))),
            )
            .await;

        if let Some(loading_text) = document.get_element_by_id("loading_text") {
            match start_result {
                Ok(_) => {
                    loading_text.remove();
                }
                Err(e) => {
                    loading_text.set_inner_html(
                        "<p> The app has crashed. See the developer console for details. </p>",
                    );
                    panic!("Failed to start eframe: {e:?}");
                }
            }
        }
    });
}

use bevy::ecs::entity::MapEntities;
use bevy::prelude::*;
