//! Shared types for FFI between bevy-moder host and WASM mods.
//!
//! These types are `#[repr(C)]` and must be compatible with the WASM32 target,
//! where pointers and `usize` are 32-bit.

/// System info: metadata for a mod system exported to the host.
#[repr(C)]
#[derive(Debug)]
pub struct SystemInfo {
    /// The exported function name (null-terminated C string).
    pub export_name: [u8; 64],
    /// 0 = Update, 1 = Startup.
    pub schedule: u8,
}

/// Result passed between WASM mod and host after a query.
///
/// Pointers and lengths are `u32` for WASM32 compatibility.
#[repr(C)]
#[derive(Debug)]
pub struct HostModResult {
    /// Pointer to serialized data (in WASM linear memory).
    pub data_ptr: u32,
    /// Length of the serialized data.
    pub data_len: u32,
}

//! SDK traits and re-exports for shared type definitions.
//!
//! Types defined with [`#[component]`](macro@bevy_moder_sdk_macros::component)
//! or [`#[resource]`](macro@bevy_moder_sdk_macros::resource) in this crate
//! can be serialised and exchanged between the host and WASM mods.

pub use bevy_moder_sdk_macros::*;

/// Trait for components that can be queried by mods.
///
/// Implemented automatically by the `#[component]` macro.
pub trait Component {
    /// Returns the component ID (equal to the struct name).
    fn component_id() -> &'static str;
}

extern crate proc_macro;

use proc_macro::TokenStream;
use quote::quote;
use syn::{parse_macro_input, DeriveInput};

/// Register a Bevy **component** that mods can query / spawn.
///
/// The struct name becomes the component ID.
///
/// # Example
/// ```ignore
/// #[register_component]
/// #[derive(Component, Debug)]
/// pub struct Square(pub Vec2);
/// // id = "Square"
/// ```
#[proc_macro_attribute]
pub fn register_component(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);
    let struct_name = &derive_input.ident;
    let component_id = struct_name.to_string();

    let ctor_name = quote::format_ident!("__mod_ctor_comp_{}", struct_name);

    let expanded = quote! {
        #[derive(serde::Serialize, serde::Deserialize)]
        #[derive(bevy::prelude::Reflect)]
        #derive_input

        #[allow(non_snake_case)]
        #[ctor::ctor]
        fn #ctor_name() {
            bevy_moder_runtime::component::register_component(
                #component_id,
                (|component: bevy::ptr::Ptr<'_>| -> Vec<u8> {
                    unsafe {
                        let c = component.deref::<#struct_name>();
                        bincode::serde::encode_to_vec(c, bincode::config::standard())
                            .unwrap_or_default()
                    }
                }) as fn(bevy::ptr::Ptr<'_>) -> Vec<u8>,
                (|data: &[u8]| -> Box<dyn std::any::Any> {
                    let (v, _) = bincode::serde::decode_from_slice::<#struct_name, _>(
                        data, bincode::config::standard(),
                    ).expect("failed to deserialise mod_component");
                    Box::new(v)
                }) as fn(&[u8]) -> Box<dyn std::any::Any>,
                (|| -> std::any::TypeId {
                    std::any::TypeId::of::<#struct_name>()
                }) as fn() -> std::any::TypeId,
                (|registry: &mut bevy::reflect::TypeRegistry| {
                    registry.register::<#struct_name>();
                }) as fn(&mut bevy::reflect::TypeRegistry),
                (|entity: &mut bevy::ecs::world::EntityWorldMut,
                  component: Box<dyn std::any::Any>| {
                    if let Ok(c) = component.downcast::<#struct_name>() {
                        entity.insert(*c);
                    }
                }) as fn(&mut bevy::ecs::world::EntityWorldMut, Box<dyn std::any::Any>),
            );
        }
    };

    TokenStream::from(expanded)
}

/// Register a Bevy **resource** that mods can read.
///
/// The struct name becomes the resource ID.
///
/// # Example
/// ```ignore
/// #[register_resource]
/// #[derive(Resource, Debug)]
/// pub struct Player(pub Vec2);
/// // id = "Player"
/// ```
#[proc_macro_attribute]
pub fn register_resource(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);
    let struct_name = &derive_input.ident;
    let resource_id = struct_name.to_string();

    let ctor_name = quote::format_ident!("__mod_ctor_res_{}", struct_name);

    let expanded = quote! {
        #[derive(serde::Serialize, serde::Deserialize)]
        #[derive(bevy::prelude::Reflect)]
        #derive_input

        #[allow(non_snake_case)]
        #[ctor::ctor]
        fn #ctor_name() {
            bevy_moder_runtime::resource::register_resource(
                #resource_id,
                (|resource: bevy::ptr::Ptr<'_>| -> Vec<u8> {
                    unsafe {
                        let r = resource.deref::<#struct_name>();
                        bincode::serde::encode_to_vec(r, bincode::config::standard())
                            .unwrap_or_default()
                    }
                }) as fn(bevy::ptr::Ptr<'_>) -> Vec<u8>,
                (|data: &[u8]| -> Box<dyn std::any::Any> {
                    let (v, _) = bincode::serde::decode_from_slice::<#struct_name, _>(
                        data, bincode::config::standard(),
                    ).expect("failed to deserialise mod_resource");
                    Box::new(v)
                }) as fn(&[u8]) -> Box<dyn std::any::Any>,
                (|| -> std::any::TypeId {
                    std::any::TypeId::of::<#struct_name>()
                }) as fn() -> std::any::TypeId,
                (|registry: &mut bevy::reflect::TypeRegistry| {
                    registry.register::<#struct_name>();
                }) as fn(&mut bevy::reflect::TypeRegistry),
                (|world: &mut bevy::prelude::World, component: Box<dyn std::any::Any>| {
                    if let Ok(c) = component.downcast::<#struct_name>() {
                        world.insert_resource(*c);
                    }
                }) as fn(&mut bevy::prelude::World, Box<dyn std::any::Any>),
            );
        }
    };

    TokenStream::from(expanded)
}

#[proc_macro_attribute]
pub fn register_message(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);
    let struct_name = &derive_input.ident;
    let type_name = struct_name.to_string();

    let ctor_name = quote::format_ident!("__mod_ctor_msg_{}", struct_name);

    let expanded = quote! {
        #[derive(serde::Serialize, serde::Deserialize)]
        #derive_input
        impl bevy::ecs::message::Message for #struct_name {}

        #[allow(non_snake_case)]
        #[ctor::ctor]
        fn #ctor_name() {
            bevy_moder_runtime::message::register_message(
                bevy_moder_runtime::message::MessageRegistration {
                    type_name: #type_name,
                    serialize_fn: (|v: &(dyn std::any::Any + Send + Sync)| -> Vec<u8> {
                        let msg = v.downcast_ref::<#struct_name>().expect("register_message serialise");
                        bincode::serde::encode_to_vec(msg, bincode::config::standard())
                            .unwrap_or_default()
                    }) as fn(&(dyn std::any::Any + Send + Sync)) -> Vec<u8>,
                    deserialize_fn: (|data: &[u8]| -> Box<dyn std::any::Any + Send + Sync> {
                        let (v, _) = bincode::serde::decode_from_slice::<#struct_name, _>(
                            data, bincode::config::standard(),
                        ).expect("failed to deserialise message");
                        Box::new(v)
                    }) as fn(&[u8]) -> Box<dyn std::any::Any + Send + Sync>,
                    write_fn: (|world: &mut bevy::prelude::World, data: Vec<u8>| {
                        let (msg, _): (#struct_name, _) =
                            bincode::serde::decode_from_slice(&data, bincode::config::standard())
                                .expect("write_fn deserialise");
                        world.init_resource::<bevy::ecs::message::Messages<#struct_name>>();
                        world.resource_mut::<bevy::ecs::message::Messages<#struct_name>>()
                            .write(msg);
                    }) as fn(&mut bevy::prelude::World, Vec<u8>),
                    drain_fn: (|world: &mut bevy::prelude::World| -> Vec<u8> {
                        let msgs: Vec<#struct_name> =
                            match world.get_resource_mut::<bevy::ecs::message::Messages<#struct_name>>()
                            {
                                Some(mut m) => m.drain().collect(),
                                None => return vec![],
                            };
                        bincode::serde::encode_to_vec(&msgs, bincode::config::standard())
                            .unwrap_or_default()
                    }) as fn(&mut bevy::prelude::World) -> Vec<u8>,
                },
            );
        }
    };

    TokenStream::from(expanded)
}

use bevy::ecs::entity::EntityHashMap;
use bevy::prelude::*;

pub(crate) fn save(world: &mut World, filename: String) {
    let entities: Vec<_> = world.query::<Entity>().iter(world).collect();
    let registry = world.resource::<AppTypeRegistry>().clone();
    let scene = make_scene(world, entities.into_iter());
    paiagram_rw::save::save(scene, registry, filename);
}

pub(crate) fn save_ron(world: &mut World, filename: String) {
    let entities: Vec<_> = world.query::<Entity>().iter(world).collect();
    let registry = world.resource::<AppTypeRegistry>().clone();
    let scene = make_scene(world, entities.into_iter());
    paiagram_rw::save::save_ron(scene, registry, filename);
}

pub(crate) fn apply_loaded_scene(world: &mut World) {
    let Some(loaded) = world.remove_resource::<paiagram_rw::save::LoadedScene>() else {
        return;
    };
    let mut entity_map = EntityHashMap::default();
    loaded.0.write_to_world(world, &mut entity_map).unwrap();
}

// TODO: remove make scene and replace with custom CBOR structs
// DynamicScene is not stable
fn make_scene(world: &World, entities: impl Iterator<Item = Entity>) -> DynamicScene {
    DynamicSceneBuilder::from_world(world)
        .deny_all_resources()
        .allow_resource::<crate::MainUiState>()
        .allow_resource::<crate::GlobalTimer>()
        .allow_resource::<crate::actions::ActionHistory>()
        .allow_resource::<paiagram_core::settings::ProjectSettings>()
        .allow_resource::<paiagram_core::graph::Graph>()
        .allow_all_components()
        .extract_entities(entities)
        .extract_resources()
        .build()
}

