use bevy::prelude::*;
use bevy_moder_runtime::{ModLoader, ModUnloader, WasmModPlugin};
use paiagram_core::settings::UserPreferences;

// Resource tracking all discovered .wasm files
#[derive(Resource, Default)]
pub struct AvailableMods {
    pub mods: Vec<ModEntry>,
}

pub struct ModEntry {
    pub name: String,
    pub path: String,
    pub enabled: bool,
}

// Plugin for mod management
pub struct PaiagramModsPlugin;

impl Plugin for PaiagramModsPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<AvailableMods>()
           .add_systems(Startup, scan_mods_directory)
           .add_systems(Update, sync_mod_states);
    }
}

// Scan the mods directory for .wasm files
fn scan_mods_directory(mut available: ResMut<AvailableMods>) {
    let exe_path = std::env::current_exe().ok();
    let exe_dir = exe_path.and_then(|p| p.parent().map(|p| p.to_path_buf()));
    let mods_dir = exe_dir.map(|p| p.join("mods"));

    let mods_dir = match mods_dir {
        Some(d) if d.exists() => d,
        _ => {
            // Try current dir /mods as fallback during development
            let fallback = std::path::PathBuf::from("mods");
            if fallback.exists() { fallback } else { return; }
        }
    };

    let mut mods = Vec::new();
    if let Ok(entries) = std::fs::read_dir(&mods_dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) == Some("wasm") {
                let name = path.file_stem()
                    .and_then(|n| n.to_str())
                    .unwrap_or("unknown")
                    .to_string();
                let path_str = path.to_string_lossy().to_string();
                mods.push(ModEntry { name, path: path_str, enabled: false });
            }
        }
    }
    available.mods = mods;
}

// Extract mod names set from UserPreferences
fn get_enabled_mods(preferences: &UserPreferences) -> std::collections::HashSet<String> {
    preferences.enabled_mods.iter().cloned().collect()
}

// Sync mods: load newly enabled, unload newly disabled
fn sync_mod_states(
    mut loader: ResMut<ModLoader>,
    mut unloader: ResMut<ModUnloader>,
    available: Res<AvailableMods>,
    preferences: Res<UserPreferences>,
) {
    // Check if preferences changed
    if !preferences.is_changed() && !available.is_changed() {
        return;
    }

    let enabled = get_enabled_mods(&preferences);

    // For each available mod, check if we need to load/unload
    // Note: we use ModLoader.load() to load, ModUnloader.unload() to unload
    // The actual mod name is the .wasm filename without extension

    for mod_entry in &available.mods {
        let name = &mod_entry.name;
        if enabled.contains(name) {
            // Load if not already loaded - ModLoader's dedup handles it
            loader.load(mod_entry.path.clone());
        } else {
            // Unload
            unloader.unload(name.clone());
        }
    }
}
```

