//! Paiagram SDK — shared types for Paiagram mod developers.
//!
//! Mods written for Paiagram should depend on this crate and use the
//! re-exported macros to define component, resource, and message types
//! that the Paiagram host can read/write.
//!
//! # Example
//! ```ignore
//! use paiagram_sdk::*;
//!
//! #[component]
//! pub struct MyModData(pub f32);
//!
//! #[resource]
//! pub struct MyModConfig {
//!     pub enabled: bool,
//! }
//! ```

pub use bevy_moder_sdk::*;

//! WASM mod management for Paiagram.
//!
//! Discovers `.wasm` files in the `mods/` directory next to the executable
//! and provides the resource used by the Settings tab for dynamic loading
//! and unloading.

/// Resource tracking all discovered WASM mod files.
/// Only available on native (non-WASM) targets.
#[cfg(not(target_arch = "wasm32"))]
#[derive(bevy::prelude::Resource, Default)]
pub struct AvailableMods {
    pub mods: Vec<ModEntry>,
}

/// A single discovered WASM mod on disk.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone, Debug)]
pub struct ModEntry {
    /// File stem (filename without `.wasm`), used as the mod identifier.
    pub name: String,
    /// Full filesystem path to the `.wasm` file.
    pub path: String,
}

/// Plugin that integrates WASM mod support into Paiagram.
///
/// Only compiled on native targets because wasmtime does not support
/// wasm32 as a host architecture.
#[cfg(not(target_arch = "wasm32"))]
pub struct PaiagramModsPlugin;

#[cfg(not(target_arch = "wasm32"))]
impl bevy::prelude::Plugin for PaiagramModsPlugin {
    fn build(&self, app: &mut bevy::prelude::App) {
        // Core wasm runtime from bevy-moder
        app.add_plugins(bevy_moder_runtime::WasmModPlugin::default());
        // Our own resource for discovered mod files
        app.init_resource::<AvailableMods>();
        // Scan the mods directory once at startup
        app.add_systems(bevy::prelude::Startup, scan_mods_directory);
    }
}

#[cfg(not(target_arch = "wasm32"))]
fn scan_mods_directory(mut available: bevy::prelude::ResMut<AvailableMods>) {
    use bevy::prelude::*;

    fn mods_directory() -> Option<std::path::PathBuf> {
        // Primary: next to the executable
        if let Ok(exe) = std::env::current_exe() {
            if let Some(parent) = exe.parent() {
                let d = parent.join("mods");
                if d.is_dir() {
                    return Some(d);
                }
            }
        }
        // Fallback: current working directory (useful during development)
        let d = std::path::PathBuf::from("mods");
        if d.is_dir() {
            return Some(d);
        }
        None
    }

    let Some(dir) = mods_directory() else {
        return;
    };

    let mut mods = Vec::new();
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().is_some_and(|e| e == "wasm") {
                let name = path
                    .file_stem()
                    .and_then(|n| n.to_str())
                    .unwrap_or("unknown")
                    .to_string();
                mods.push(ModEntry {
                    name,
                    path: path.to_string_lossy().to_string(),
                });
            }
        }
    }
    mods.sort_by(|a, b| a.name.cmp(&b.name));
    available.mods = mods;
}

