//! Bevy Moder Runtime
//!
//! Host-side runtime that loads WASM mods, links them to the Bevy ECS,
//! and executes their systems.  Communication happens over a simple
//! FFI layer (bincode-serialised data passed through WASM linear memory).

pub mod component;
pub mod log;
pub mod message;
pub mod mod_types;
pub mod query;
pub mod resource;
pub mod spawn;
pub mod system;

use bevy::ecs::world::unsafe_world_cell::UnsafeWorldCell;
use bevy::log::*;
use bevy::prelude::*;
use bevy_moder_types::SystemInfo;
use std::cell::UnsafeCell;
use std::collections::HashMap;
use std::sync::{Arc, Mutex, RwLock};
use wasmtime::{Engine, Instance, Linker, Module, Store};
use wasmtime_wasi::p1::{WasiP1Ctx, add_to_linker_sync};
use wasmtime_wasi::WasiCtxBuilder;

pub use component::{ComponentRegistration, iter_components};
pub use message::{MessageRegistration, MessageBuffer, iter_messages};
pub use resource::{ResourceRegistration, iter_resources};
pub use system::{ModSystems, execute_mod_update_systems};

pub use mod_types::ModComponents;
pub use ctor;
pub use serde;
pub use bincode;

pub use bevy_moder_runtime_macros::{register_component, register_resource, register_message};

/// Bevy plugin that loads and manages WASM mods.
///
/// Mod paths supplied via [`add_mod_path`](WasmModPlugin::add_mod_path) are
/// queued in [`ModLoader`] and loaded at runtime.  Additional mods can be
/// loaded dynamically through [`ModLoader::load`].
#[derive(Debug, Resource, Clone)]
pub struct WasmModPlugin {
    /// Paths to `.wasm` files to load.
    pub mod_paths: Vec<String>,
}

impl Default for WasmModPlugin {
    fn default() -> Self {
        Self {
            mod_paths: Vec::new(),
        }
    }
}

impl WasmModPlugin {
    pub fn add_mod_path(mut self, path: impl Into<String>) -> Self {
        self.mod_paths.push(path.into());
        self
    }

    pub fn set_mod_paths(mut self, paths: Vec<String>) -> Self {
        self.mod_paths = paths;
        self
    }
}

impl Plugin for WasmModPlugin {
    fn build(&self, app: &mut App) {
        let initial_paths = self.mod_paths.clone();

        app.insert_resource(ModLoader::with_pending(initial_paths))
            .insert_resource(ModUnloader::default())
            .insert_resource(LoadedMods(HashMap::new()))
            .insert_resource(ModSystems(Vec::new()))
            .insert_resource(MessageBuffer::default());

        app.add_systems(Startup, load_world);
        app.add_systems(PreUpdate, (
            process_mod_unloader_queue,
            process_mod_loader_queue,
        ).chain());
        app.add_systems(PostUpdate, (
            message::buffer_messages_for_mod,
            execute_mod_update_systems,
            message::flush_messages_from_mod,
        ).chain());
    }
}

/// Queues WASM mod paths for loading.  Used by the plugin for initial paths
/// and by user systems for dynamic loading.
#[derive(Resource)]
pub struct ModLoader {
    pending: Vec<String>,
}

impl ModLoader {
    /// Create a loader with a list of initial paths.
    pub fn with_pending(paths: Vec<String>) -> Self {
        Self { pending: paths }
    }

    /// Queue a WASM module for loading on the next frame.
    pub fn load(&mut self, path: impl Into<String>) {
        self.pending.push(path.into());
    }

    /// Load a WASM module **synchronously** and return its name.
    ///
    /// Compiles, instantiates, and registers the mod immediately.
    /// Returns the mod's declared name (from `mod_def!`) on success.
    ///
    /// This is a static function — it takes `&mut World` directly, so it
    /// can be called from an exclusive system without a borrow conflict.
    ///
    /// ```ignore
    /// fn my_system(world: &mut World) {
    ///     match ModLoader::load_sync(world, "path/to/mod.wasm") {
    ///         Ok(name) => info!("Loaded mod: {name}"),
    ///         Err(e) => error!("Failed: {e}"),
    ///     }
    /// }
    /// ```
    pub fn load_sync(
        world: &mut World,
        path: impl Into<String>,
    ) -> Result<String, String> {
        let engine = Engine::default();
        load_single_mod(world, &engine, &path.into())
    }
}

/// Queue mod names for unloading.
#[derive(Resource, Default)]
pub struct ModUnloader {
    pending: Vec<String>,
}

impl ModUnloader {
    /// Queue a mod for unloading by its name.
    pub fn unload(&mut self, mod_name: impl Into<String>) {
        self.pending.push(mod_name.into());
    }
}

/// All successfully loaded mods.
#[derive(Resource)]
pub struct LoadedMods(pub HashMap<String, LoadedMod>);

/// A single loaded WASM mod.
pub struct LoadedMod {
    pub system_infos: HashMap<String, SystemInfo>,
    pub instance: Instance,
    pub store: Arc<RwLock<Store<ModState>>>,
}

/// Per-mod runtime state stored inside the wasmtime `Store`.
pub struct ModState {
    wasi_ctx: Arc<Mutex<UnsafeCell<WasiP1Ctx>>>,
    world: Option<Arc<UnsafeWorldCell<'static>>>,
}

impl ModState {
    pub fn new(wasi_ctx: WasiP1Ctx) -> Self {
        Self {
            wasi_ctx: Arc::new(Mutex::new(UnsafeCell::new(wasi_ctx))),
            world: None,
        }
    }

    pub fn get_wasi_ctx_mut(&mut self) -> &mut WasiP1Ctx {
        unsafe { &mut *self.wasi_ctx.lock().unwrap().get() }
    }

    pub fn set_world(&mut self, world: Arc<UnsafeWorldCell<'static>>) {
        self.world = Some(world);
    }

    pub fn get_world(&self) -> Option<UnsafeWorldCell<'static>> {
        self.world.clone().map(|w| *w)
    }
}

/// Compile, link, and instantiate one WASM module, then register its
/// components, resources, and systems in the Bevy world.
///
/// Called from [`process_mod_loader_queue`] for both initial and
/// dynamically-loaded mods.
fn load_single_mod(world: &mut World, engine: &Engine, path: &str) -> Result<String, String> {
    let module = Module::from_file(engine, path).map_err(|e| format!("compile: {e}"))?;

    let mut linker: Linker<ModState> = Linker::new(engine);
    add_to_linker_sync(&mut linker, |state| state.get_wasi_ctx_mut())
        .map_err(|e| format!("wasi linker: {e}"))?;

    macro_rules! link {
        ($name:literal, $func:expr) => {
            linker
                .func_wrap("env", $name, $func)
                .map_err(|e| format!("link '{name}': {e}", name = $name))?;
        };
    }
    link!("__mod_log", log::host_handle_log);
    link!("__mod_query_components", query::host_handle_query_components);
    link!("__mod_query_resources", resource::host_handle_query_resources);
    link!("__mod_free_memory", system::host_handle_free_memory);
    link!("__mod_spawn_entities", spawn::host_handle_spawn_entities);
    link!("__mod_set_resource", resource::host_handle_set_resource);
    link!("__mod_update_components", query::host_handle_update_components);
    link!("__mod_read_messages", message::host_handle_read_messages);
    link!("__mod_write_message", message::host_handle_write_message);

    let state = ModState::new(WasiCtxBuilder::new().inherit_env().args(&[path]).build_p1());
    let mut store = Store::new(engine, state);

    let instance = linker
        .instantiate(&mut store, &module)
        .map_err(|e| format!("instantiate: {e}"))?;

    let mod_name = system::get_mod_name(&mut store, &instance)
        .map_err(|e| format!("read mod name: {e}"))?;
    info!("Loading mod '{mod_name}' from '{path}'");

    let system_names = system::get_systems(&mut store, &instance)
        .map_err(|e| format!("read systems: {e}"))?;

    let mut system_infos: HashMap<String, SystemInfo> = HashMap::new();
    let store_arc = Arc::new(RwLock::new(store));

    {
        let mut s = store_arc.write().unwrap();

        for sys_name in &system_names {
            let info = system::get_mod_system_info(&mut *s, &instance, sys_name)
                .map_err(|e| format!("system info '{sys_name}': {e}"))?;

            let export_name = system::system_info_export_name_str(&info);
            info!("  System '{sys_name}' → export '{export_name}' schedule {}", info.schedule);

            let func = instance
                .get_typed_func::<(), ()>(&mut *s, &export_name)
                .map_err(|e| format!("get func '{export_name}': {e}"))?;

            let mut mod_systems = world.resource_mut::<ModSystems>();
            mod_systems.0.push(system::ModSystemInfo {
                mod_name: mod_name.clone(),
                schedule: system::ModSystemSchedule::from(info.schedule),
                run_func: func,
            });

            system_infos.insert(sys_name.clone(), info);
        }

        system::get_mod_custom_types(&mut *s, &instance, &mod_name);
    }

    let world_cell = unsafe {
        std::mem::transmute::<UnsafeWorldCell<'_>, UnsafeWorldCell<'static>>(
            world.as_unsafe_world_cell(),
        )
    };
    {
        let mut s = store_arc.write().unwrap();
        s.data_mut().set_world(Arc::new(world_cell));
    }

    let mut loaded = world.resource_mut::<LoadedMods>();
    loaded.0.insert(
        mod_name.clone(),
        LoadedMod {
            system_infos,
            instance,
            store: store_arc.clone(),
        },
    );

    run_startup_systems(&mod_name, world);

    info!("Mod '{mod_name}' loaded successfully");
    Ok(mod_name)
}

/// Run every Startup-system registered for a given mod.
fn run_startup_systems(mod_name: &str, world: &mut World) {
    let loaded = world.resource::<LoadedMods>();
    let mod_systems = world.resource::<ModSystems>();
    for info in &mod_systems.0 {
        if info.mod_name != mod_name || info.schedule != system::ModSystemSchedule::Startup {
            continue;
        }
        let store_arc = match loaded.0.get(&info.mod_name) {
            Some(m) => m.store.clone(),
            None => continue,
        };
        let mut s = store_arc.write().unwrap();
        if let Err(e) = info.run_func.call(&mut *s, ()) {
            error!("Startup system '{}' failed: {e}", info.mod_name);
        }
    }
}

/// Exclusive system that drains [`ModLoader`] and loads every pending mod.
///
/// Runs in `PreUpdate` so newly loaded mods execute their Update systems
/// in the same frame's `PostUpdate`.
pub fn process_mod_loader_queue(world: &mut World) {
    let loader = match world.get_resource::<ModLoader>() {
        Some(l) => l,
        None => return,
    };
    if loader.pending.is_empty() {
        return;
    }

    let paths = {
        let mut l = world.resource_mut::<ModLoader>();
        std::mem::take(&mut l.pending)
    };

    let engine = Engine::default();
    for path in paths {
        match load_single_mod(world, &engine, &path) {
            Ok(name) => info!("  → loaded '{name}'"),
            Err(e) => error!("Failed to load mod '{path}': {e}"),
        }
    }
}

/// Remove a loaded mod from the world, stopping its systems and
/// freeing its WASM instance.
pub fn unload_single_mod(world: &mut World, mod_name: &str) -> Result<(), String> {
    let mut sys = world.resource_mut::<ModSystems>();
    sys.0.retain(|info| info.mod_name != mod_name);

    let mut loaded = world.resource_mut::<LoadedMods>();
    loaded
        .0
        .remove(mod_name)
        .ok_or_else(|| format!("mod '{mod_name}' is not loaded"))?;

    mod_types::remove_all_for_mod(mod_name);

    info!("Unloaded mod '{mod_name}'");
    Ok(())
}

/// Exclusive system that drains [`ModUnloader`] and unloads every
/// pending mod.  Runs in `PreUpdate` **before** the loader queue so
/// that a reload (unload + load) works within the same frame.
pub fn process_mod_unloader_queue(world: &mut World) {
    let unloader = match world.get_resource::<ModUnloader>() {
        Some(u) => u,
        None => return,
    };
    if unloader.pending.is_empty() {
        return;
    }

    let names = {
        let mut u = world.resource_mut::<ModUnloader>();
        std::mem::take(&mut u.pending)
    };

    for name in names {
        match unload_single_mod(world, &name) {
            Ok(()) => info!("  → unloaded '{name}'"),
            Err(e) => error!("Failed to unload mod '{name}': {e}"),
        }
    }
}

fn load_world(world: &mut World) {
    {
        let type_reg = world.resource_mut::<AppTypeRegistry>();
        let mut registry = type_reg.write();
        for reg in component::iter_components() {
            (reg.reg_fn)(&mut registry);
        }
        for reg in resource::iter_resources() {
            (reg.reg_fn)(&mut registry);
        }
        registry.register::<mod_types::ModComponents>();
        registry.register::<mod_types::ModResources>();
    }

    world.insert_resource(mod_types::ModResources {
        data: std::collections::HashMap::new(),
    });

    let mut seen = HashMap::new();
    for reg in component::iter_components() {
        if let Some(prev) = seen.insert(reg.id, "component") {
            panic!(
                "[bevy-moder] duplicate component ID '{}' (already registered as {}).",
                reg.id, prev,
            );
        }
    }
    for reg in resource::iter_resources() {
        if let Some(prev) = seen.insert(reg.id, "resource") {
            panic!(
                "[bevy-moder] duplicate resource ID '{}' (already registered as {}).",
                reg.id, prev,
            );
        }
    }
}

