/// Mod management section — only compiled on native targets.
#[cfg(not(target_arch = "wasm32"))]
fn show_mod_settings(
    InMut(ui): InMut<Ui>,
    mut preferences: ResMut<UserPreferences>,
    mut loader: ResMut<bevy_moder_runtime::ModLoader>,
    mut unloader: ResMut<bevy_moder_runtime::ModUnloader>,
    available: Res<AvailableMods>,
) {
    ui.separator();
    ui.heading(tr!("settings-mods"));

    if available.mods.is_empty() {
        ui.label(tr!("settings-no-mods-found"));
        return;
    }

    for mod_entry in &available.mods {
        let mut enabled = preferences.enabled_mods.contains(&mod_entry.name);
        let prev = enabled;
        ui.checkbox(&mut enabled, &mod_entry.name);
        if enabled && !prev {
            // User just enabled this mod — load it dynamically
            preferences.enabled_mods.push(mod_entry.name.clone());
            loader.load(mod_entry.path.clone());
            bevy::log::info!("Mod enabled: {} ({})", mod_entry.name, mod_entry.path);
        } else if !enabled && prev {
            // User just disabled this mod — unload it dynamically
            preferences.enabled_mods.retain(|n| n != &mod_entry.name);
            unloader.unload(mod_entry.name.clone());
            bevy::log::info!("Mod disabled: {}", mod_entry.name);
        }
    }
}

