content.thinking:
The issue is in `process_mod_actions`. I'm calling `world.resource_mut::<ModNameRegistry>()` to get the registry, and then inside the loop, calling `bevy_moder_runtime::unload_single_mod(world, &name)` which also needs `&mut World`. This is a double borrow.

I need to restructure the code. The `unload_single_mod` takes `&mut World`, so I can't hold a `ResMut` at the same time.

The fix is to either:
1. Clone the needed data out of the registry first, then process separately
2. Use `world.resource_scope` for the registry parts
3. Separate the registry lookup from the unload calls

Let me restructure:

```rust
fn process_mod_actions(world: &mut World) {
    let items = {
        let mut q = world.resource_mut::<ModActionQueue>();
        std::mem::take(&mut q.items)
    };
    if items.is_empty() {
        return;
    }

    let mut unloads = Vec::new();
    let mut loads = Vec::new();
    for a in items {
        match a {
            ModAction::Load(p) => loads.push(p),
            ModAction::Unload(p) => unloads.push(p),
        }
    }

    // First, resolve unload paths to names (without borrowing registry later)
    let unload_names: Vec<(String, String)> = {
        let registry = world.resource::<ModNameRegistry>();
        unloads.iter()
            .filter_map(|path| {
                registry.path_to_name.get(path)
                    .map(|name| (path.clone(), name.clone()))
            })
            .collect()
    };

    // Remove from registry
    {
        let mut registry = world.resource_mut::<ModNameRegistry>();
        for (path, _) in &unload_names {
            registry.path_to_name.remove(path);
        }
    }

    // Unload (no registry borrow active)
    for (_, name) in &unload_names {
        if let Err(e) = bevy_moder_runtime::unload_single_mod(world, name) {
            bevy::log::error!("Failed to unload mod '{}': {}", name, e);
        } else {
            bevy::log::info!("Unloaded mod '{}'", name);
        }
    }

    // Process loads
    for path in &loads {
        match bevy_moder_runtime::ModLoader::load_sync(world, path) {
            Ok(name) => {
                bevy::log::info!("Loaded mod '{}' from {}", name, path);
                let mut registry = world.resource_mut::<ModNameRegistry>();
                registry.path_to_name.insert(path.clone(), name);
            }
            Err(e) => {
                bevy::log::error!("Failed to load mod '{}': {}", path, e);
            }
        }
    }
}
